resource "ansible_navigator_run" "ntfy_provision" {
  triggers = {
    container_id = module.monitoring.container_id
    container_ip = module.monitoring.ip_address
    # Re-run if credentials change
    credentials_hash = sha256(join(",", [
      local.op.ntfy_admin_password,
      local.op.ntfy_darshan_password,
      local.op.ntfy_alertmanager_password,
      local.op.ntfy_pbs_backup_password,
      local.op.ntfy_n8n_password,
    ]))
  }

  execution_environment = {
    enabled = false
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.ssh_private_key_path)
    }]
  }

  playbook = templatefile("${path.module}/deploy/ntfy/provision-users.yml.tpl", {
    ntfy_admin_user            = local.op.ntfy_admin_user
    ntfy_admin_password        = local.op.ntfy_admin_password
    ntfy_darshan_password      = local.op.ntfy_darshan_password
    ntfy_alertmanager_password = local.op.ntfy_alertmanager_password
    ntfy_pbs_backup_password   = local.op.ntfy_pbs_backup_password
    ntfy_n8n_password          = local.op.ntfy_n8n_password
  })

  inventory = yamlencode({
    monitoring = {
      hosts = {
        "monitoring" = {
          ansible_host = module.monitoring.ip_address
          ansible_user = "root"
        }
      }
    }
  })

  depends_on = [module.monitoring]
}

# -----------------------------------------------------------------------------

# =============================================================================
# LXC Sidecars Module Variables
# =============================================================================
# This module manages sidecar services for LXC containers:
#   - Backup (proxmox-backup-client with PBS)
#   - Alloy (Grafana Alloy for log/metric collection)
#   - DIUN (Docker image update notifications) - Future
# =============================================================================

# =============================================================================
# Container Information
# =============================================================================

variable "container_id" {
  description = "LXC container ID"
  type        = number
}

variable "container_ip" {
  description = "Container IP address (without CIDR)"
  type        = string
}

variable "container_name" {
  description = "Container hostname"
  type        = string
}

# =============================================================================
# Proxmox SSH Connection (for Ansible deployment)
# =============================================================================

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address"
  type        = string
}

variable "proxmox_ssh_private_key_path" {
  description = "Path to SSH private key for Proxmox host"
  type        = string
}

# =============================================================================
# Backup Configuration
# =============================================================================

variable "backup" {
  description = "Backup configuration for PBS client"
  type = object({
    enabled     = bool
    schedule    = string                    # "daily", "02:00", "Sun 03:00"
    retention   = optional(string, "7")     # Keep N backups
    namespace   = string                    # PBS namespace (usually container name)

    # Pre-backup commands (database dumps, etc.)
    pre_backup_commands = optional(list(object({
      name    = string
      command = string
      timeout = optional(number, 300)
    })), [])

    # Paths to backup/exclude
    include_paths = optional(list(string), ["/config"])
    exclude_paths = optional(list(string), ["/var/lib/docker/overlay2"])

    # PBS server settings
    pbs_server     = optional(string, "10.100.1.102")
    pbs_datastore  = optional(string, "homelab")
    pbs_user       = optional(string, "backup@pbs")
    pbs_password_cmd = optional(string, "op read 'op://homelab/PBS - Proxmox Backup Server/password'")

    # Alert settings
    ntfy_url           = optional(string, "http://10.100.5.100:8080/backup-alerts")
    ntfy_priority      = optional(string, "default")
    ntfy_tags          = optional(string, "backup")
    ntfy_user          = optional(string, "")   # ntfy username for authentication
    ntfy_password      = optional(string, "")   # ntfy password for authentication
    notify_on_success  = optional(bool, true)   # Send notification on successful backup
    notify_on_failure  = optional(bool, true)   # Send notification on failed backup (recommended: always true)
  })
  default = null

  validation {
    condition = var.backup == null || (
      var.backup.enabled == true && var.backup.namespace != ""
    )
    error_message = "If backup is enabled, namespace must be provided."
  }

  validation {
    condition = var.backup == null || (
      var.backup.schedule == "daily" ||
      can(regex("^[0-9]{2}:[0-9]{2}$", var.backup.schedule)) ||
      can(regex("^(mon|tue|wed|thu|fri|sat|sun) [0-9]{2}:[0-9]{2}$", lower(var.backup.schedule)))
    )
    error_message = "Schedule must be 'daily', 'HH:MM', or 'day HH:MM' (e.g., 'Sun 03:00')."
  }
}

# =============================================================================
# Container Management Agents
# =============================================================================

variable "pulse_agent" {
  description = "Pulse Docker agent configuration for container monitoring"
  type = object({
    enabled     = optional(bool, false)
    pulse_url   = optional(string, "http://10.100.1.104:7655")
    pulse_token = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.pulse_agent.enabled, false) == false || try(var.pulse_agent.pulse_token, "") != ""
    error_message = "If pulse_agent is enabled, pulse_token must be provided."
  }
}

variable "arcane_agent" {
  description = "Arcane remote agent configuration for container management"
  type = object({
    enabled         = optional(bool, false)
    manager_url     = optional(string, "http://10.100.1.104:3552")
    bootstrap_token = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.arcane_agent.enabled, false) == false || try(var.arcane_agent.bootstrap_token, "") != ""
    error_message = "If arcane_agent is enabled, bootstrap_token must be provided."
  }
}

# =============================================================================
# Grafana Alloy Agent
# =============================================================================

variable "alloy_agent" {
  description = "Grafana Alloy agent for log/metric collection to Loki/Prometheus"
  type = object({
    enabled        = optional(bool, false)
    loki_url       = optional(string, "https://loki-push.homelab.rambtech.dev")
    prometheus_url = optional(string, "https://prometheus-push.homelab.rambtech.dev")
    username       = optional(string, "")
    password       = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.alloy_agent.enabled, false) == false || (
      try(var.alloy_agent.username, "") != "" && try(var.alloy_agent.password, "") != ""
    )
    error_message = "If alloy_agent is enabled, username and password must be provided for authentication."
  }
}

# =============================================================================
# Future Sidecars (Placeholder)
# =============================================================================

variable "diun_enabled" {
  description = "Enable DIUN for Docker image update notifications"
  type        = bool
  default     = false
}

# =============================================================================
# LXC Sidecars Module
# =============================================================================
# Manages sidecar services for LXC containers:
#   - Backup: proxmox-backup-client with PBS integration
#   - Pulse Agent: Docker monitoring agent
#   - Arcane Agent: Remote container management agent
#   - Alloy Agent: Grafana Alloy for log/metric collection
#   - DIUN: Docker image update notifications (future)
# =============================================================================

# =============================================================================
# Backup Sidecar (PBS Client)
# =============================================================================

resource "ansible_navigator_run" "configure_backup" {
  count = var.backup != null && var.backup.enabled ? 1 : 0

  triggers = {
    container_id        = var.container_id
    container_ip        = var.container_ip
    namespace           = var.backup.namespace
    schedule            = var.backup.schedule
    retention           = var.backup.retention
    pre_backup_commands = jsonencode(var.backup.pre_backup_commands)
    include_paths       = jsonencode(var.backup.include_paths)
    exclude_paths       = jsonencode(var.backup.exclude_paths)
    pbs_server          = var.backup.pbs_server
    pbs_datastore       = var.backup.pbs_datastore
  }

  execution_environment = {
    enabled = false  # Run ansible directly on host, not in container
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.proxmox_ssh_private_key_path)
    }]
  }

  playbook = templatefile("${path.module}/templates/configure-backup-playbook.yml.tftpl", {
    container_id        = var.container_id
    container_ip        = var.container_ip
    container_name      = var.container_name
    namespace           = var.backup.namespace
    schedule            = var.backup.schedule
    retention           = var.backup.retention
    pre_backup_commands = var.backup.pre_backup_commands
    include_paths       = var.backup.include_paths
    exclude_paths       = var.backup.exclude_paths
    pbs_server          = var.backup.pbs_server
    pbs_datastore       = var.backup.pbs_datastore
    pbs_user            = var.backup.pbs_user
    pbs_password_cmd    = var.backup.pbs_password_cmd
    ntfy_url            = var.backup.ntfy_url
    ntfy_priority       = var.backup.ntfy_priority
    ntfy_tags           = var.backup.ntfy_tags
    backup_script       = templatefile("${path.module}/templates/pbs-backup.sh.tftpl", {
      container_id        = var.container_id
      container_name      = var.container_name
      namespace           = var.backup.namespace
      schedule            = var.backup.schedule
      retention           = var.backup.retention
      pre_backup_commands = var.backup.pre_backup_commands
      include_paths       = var.backup.include_paths
      exclude_paths       = var.backup.exclude_paths
      ntfy_url            = var.backup.ntfy_url
      ntfy_priority       = var.backup.ntfy_priority
      ntfy_tags           = var.backup.ntfy_tags
      ntfy_user           = var.backup.ntfy_user
      ntfy_password       = var.backup.ntfy_password
      notify_on_success   = var.backup.notify_on_success
      notify_on_failure   = var.backup.notify_on_failure
    })
  })

  inventory = yamlencode({
    lxc = {
      hosts = {
        (var.container_name) = {
          ansible_host = var.container_ip
          ansible_user = "root"
        }
      }
    }
  })
}

# =============================================================================
# Container Management Agents (Pulse + Arcane + Alloy)
# =============================================================================
# Deploys all enabled agents in a single docker-compose file to avoid conflicts.
# All agents share the same compose file at /config/sidecars/docker-compose.yml

locals {
  # Check if any agent is enabled
  any_agent_enabled = (
    try(var.pulse_agent.enabled, false) ||
    try(var.arcane_agent.enabled, false) ||
    try(var.alloy_agent.enabled, false)
  )
}

resource "ansible_navigator_run" "configure_agents" {
  count = local.any_agent_enabled ? 1 : 0

  triggers = {
    container_id    = var.container_id
    container_ip    = var.container_ip
    pulse_enabled   = try(var.pulse_agent.enabled, false)
    pulse_url       = try(var.pulse_agent.pulse_url, "")
    pulse_token     = try(var.pulse_agent.enabled, false) ? sha256(var.pulse_agent.pulse_token) : ""
    arcane_enabled  = try(var.arcane_agent.enabled, false)
    manager_url     = try(var.arcane_agent.manager_url, "")
    bootstrap_token = try(var.arcane_agent.enabled, false) ? sha256(var.arcane_agent.bootstrap_token) : ""
    alloy_enabled   = try(var.alloy_agent.enabled, false)
    loki_url        = try(var.alloy_agent.loki_url, "")
    prometheus_url  = try(var.alloy_agent.prometheus_url, "")
    alloy_auth      = try(var.alloy_agent.enabled, false) ? sha256("${var.alloy_agent.username}:${var.alloy_agent.password}") : ""
  }

  execution_environment = {
    enabled = false
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.proxmox_ssh_private_key_path)
    }]
  }

  playbook = templatefile("${path.module}/templates/configure-agents-playbook.yml.tftpl", {
    container_id    = var.container_id
    container_ip    = var.container_ip
    container_name  = var.container_name
    pulse_enabled   = try(var.pulse_agent.enabled, false)
    pulse_url       = try(var.pulse_agent.pulse_url, "http://10.100.1.104:7655")
    pulse_token     = try(var.pulse_agent.pulse_token, "")
    arcane_enabled  = try(var.arcane_agent.enabled, false)
    manager_url     = try(var.arcane_agent.manager_url, "http://10.100.1.104:3552")
    bootstrap_token = try(var.arcane_agent.bootstrap_token, "")
    alloy_enabled   = try(var.alloy_agent.enabled, false)
    loki_url        = try(var.alloy_agent.loki_url, "https://loki-push.homelab.rambtech.dev")
    prometheus_url  = try(var.alloy_agent.prometheus_url, "https://prometheus-push.homelab.rambtech.dev")
    alloy_username  = try(var.alloy_agent.username, "")
    alloy_password  = try(var.alloy_agent.password, "")
  })

  inventory = yamlencode({
    lxc = {
      hosts = {
        (var.container_name) = {
          ansible_host = var.container_ip
          ansible_user = "root"
        }
      }
    }
  })
}

# =============================================================================
# Future Sidecars (Placeholder)
# =============================================================================

# TODO: Add DIUN docker-compose deployment when diun_enabled = true

