				},
			},
			"size": schema.Int64Attribute{
				MarkdownDescription: "Size of the file in bytes.",
				Computed:            true,
				PlanModifiers: []planmodifier.Int64{
					sourceSizePlanModifier{},
				},
			},
		},
	}
