  1240→// buildTerraformValue is a helper to build terraform values for testing.
  1241→func buildTerraformValue(t *testing.T, s schema.Schema, data FileResourceModel) tftypes.Value {
  1242→	t.Helper()
  1243→
  1244→	attrTypes := s.Type().TerraformType(context.Background())
  1245→
  1246→	// Helper to convert string to value or nil for empty.
  1247→	strVal := func(s types.String) interface{} {
  1248→		if s.IsNull() || s.IsUnknown() {
  1249→			return nil
  1250→		}
  1251→		return s.ValueString()
  1252→	}
  1253→
  1254→	// Helper to convert int64 to value or nil.
  1255→	intVal := func(i types.Int64) interface{} {
  1256→		if i.IsNull() || i.IsUnknown() {
  1257→			return nil
  1258→		}
  1259→		return i.ValueInt64Pointer()
  1260→	}
  1261→
  1262→	// Helper to convert bool to value or nil.
  1263→	boolVal := func(b types.Bool) interface{} {
  1264→		if b.IsNull() || b.IsUnknown() {
  1265→			return nil
  1266→		}
  1267→		return b.ValueBool()
  1268→	}
  1269→
  1270→	vals := map[string]tftypes.Value{
  1271→		"id":                       tftypes.NewValue(tftypes.String, strVal(data.ID)),
  1272→		"source":                   tftypes.NewValue(tftypes.String, strVal(data.Source)),
  1273→		"destination":              tftypes.NewValue(tftypes.String, strVal(data.Destination)),
  1274→		"host":                     tftypes.NewValue(tftypes.String, strVal(data.Host)),
  1275→		"ssh_port":                 tftypes.NewValue(tftypes.Number, intVal(data.SSHPort)),
  1276→		"ssh_user":                 tftypes.NewValue(tftypes.String, strVal(data.SSHUser)),
  1277→		"ssh_key_path":             tftypes.NewValue(tftypes.String, strVal(data.SSHKeyPath)),
  1278→		"ssh_private_key":          tftypes.NewValue(tftypes.String, strVal(data.SSHPrivateKey)),
  1279→		"ssh_password":             tftypes.NewValue(tftypes.String, strVal(data.SSHPassword)),
  1280→		"ssh_certificate":          tftypes.NewValue(tftypes.String, strVal(data.SSHCertificate)),
  1281→		"ssh_certificate_path":     tftypes.NewValue(tftypes.String, strVal(data.SSHCertificatePath)),
  1282→		"mode":                     tftypes.NewValue(tftypes.String, strVal(data.Mode)),
  1283→		"owner":                    tftypes.NewValue(tftypes.String, strVal(data.Owner)),
  1284→		"group":                    tftypes.NewValue(tftypes.String, strVal(data.Group)),
  1285→		"bastion_host":             tftypes.NewValue(tftypes.String, strVal(data.BastionHost)),
  1286→		"bastion_port":             tftypes.NewValue(tftypes.Number, intVal(data.BastionPort)),
  1287→		"bastion_user":             tftypes.NewValue(tftypes.String, strVal(data.BastionUser)),
  1288→		"bastion_private_key":      tftypes.NewValue(tftypes.String, strVal(data.BastionKey)),
  1289→		"bastion_key_path":         tftypes.NewValue(tftypes.String, strVal(data.BastionKeyPath)),
  1290→		"bastion_password":         tftypes.NewValue(tftypes.String, strVal(data.BastionPassword)),
  1291→		"insecure_ignore_host_key": tftypes.NewValue(tftypes.Bool, boolVal(data.InsecureIgnoreHostKey)),
  1292→		"known_hosts_file":         tftypes.NewValue(tftypes.String, strVal(data.KnownHostsFile)),
  1293→		"strict_host_key_checking": tftypes.NewValue(tftypes.String, strVal(data.StrictHostKeyChecking)),
  1294→		"check_remote_on_plan":     tftypes.NewValue(tftypes.Bool, boolVal(data.CheckRemoteOnPlan)),
