				return
			}

			if hasDrift != tt.wantDrift {
				t.Errorf("checkRemoteDrift() hasDrift = %v, want %v", hasDrift, tt.wantDrift)
			}
			if remoteHash != tt.wantRemoteHash {
				t.Errorf("checkRemoteDrift() remoteHash = %v, want %v", remoteHash, tt.wantRemoteHash)
			}
		})
	}
}

