	r.Schema(context.Background(), resource.SchemaRequest{}, &schemaResp)

	// Build request with plan.
	planVal := buildTerraformValue(t, schemaResp.Schema, data)
	req := resource.CreateRequest{
		Plan: tfsdk.Plan{
			Schema: schemaResp.Schema,
			Raw:    planVal,
		},
	}

