			Plan:      plan,
			PlanValue: types.Int64Null(),
		}
		resp := &planmodifier.Int64Response{}

		m.PlanModifyInt64(context.Background(), req, resp)

		if !resp.PlanValue.IsUnknown() {
			t.Error("expected unknown value for missing file")
