	files := []struct{ Name, Source, Destination, Mode string }{
		{"file1", sourceFile1, remotePath1, "0644"},
		{"file2", sourceFile2, remotePath2, "0644"},
		{"file3", sourceFile3, remotePath3, "0644"},
