   290→
   291→// Test file creation helpers.
   292→
   293→// CreateTestSourceFile creates a temporary file with the given content for testing.
   294→func CreateTestSourceFile(t *testing.T, content string) string {
   295→	t.Helper()
   296→	tmpDir := t.TempDir()
   297→	path := filepath.Join(tmpDir, "source_file.txt")
   298→	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
   299→		t.Fatalf("failed to create test source file: %v", err)
   300→	}
   301→	return path
   302→}
   303→
   304→// CreateTestSourceDirectory creates a temporary directory with test files.
   305→func CreateTestSourceDirectory(t *testing.T, files map[string]string) string {
   306→	t.Helper()
   307→	tmpDir := t.TempDir()
   308→	srcDir := filepath.Join(tmpDir, "source")
   309→	if err := os.MkdirAll(srcDir, 0755); err != nil {
   310→		t.Fatalf("failed to create source directory: %v", err)
   311→	}
   312→
   313→	for path, content := range files {
   314→		fullPath := filepath.Join(srcDir, path)
   315→		dir := filepath.Dir(fullPath)
   316→		if err := os.MkdirAll(dir, 0755); err != nil {
   317→			t.Fatalf("failed to create directory %s: %v", dir, err)
   318→		}
   319→		if err := os.WriteFile(fullPath, []byte(content), 0644); err != nil {
   320→			t.Fatalf("failed to create file %s: %v", path, err)
   321→		}
   322→	}
   323→
   324→	return srcDir
   325→}
