   331→	path := filepath.Join(tmpDir, "source_file.bin")
   332→	if err := os.WriteFile(path, content, 0644); err != nil {
   333→		t.Fatalf("failed to create test source file: %v", err)
   334→	}
   335→	return path
   336→}
   337→
   338→// Test check functions.
   339→
   340→// CheckRemoteFileExists returns a TestCheckFunc that verifies a remote file exists.
   341→func CheckRemoteFileExists(container *SSHTestContainer, path string) resource.TestCheckFunc {
   342→	return func(s *terraform.State) error {
   343→		if !container.FileExistsNoHelper(path) {
   344→			return fmt.Errorf("remote file %s does not exist", path)
   345→		}
   346→		return nil
   347→	}
   348→}
   349→
   350→// CheckRemoteFileNotExists returns a TestCheckFunc that verifies a remote file doesn't exist.
   351→func CheckRemoteFileNotExists(container *SSHTestContainer, path string) resource.TestCheckFunc {
   352→	return func(s *terraform.State) error {
   353→		if container.FileExistsNoHelper(path) {
   354→			return fmt.Errorf("remote file %s still exists", path)
   355→		}
   356→		return nil
   357→	}
   358→}
   359→
   360→// CheckRemoteFileContent returns a TestCheckFunc that verifies remote file content.
   361→func CheckRemoteFileContent(container *SSHTestContainer, path, expected string) resource.TestCheckFunc {
   362→	return func(s *terraform.State) error {
   363→		content, err := container.ReadRemoteFileNoHelper(path)
   364→		if err != nil {
   365→			return fmt.Errorf("failed to read remote file: %w", err)
   366→		}
   367→		if content != expected {
   368→			return fmt.Errorf("remote file content mismatch:\n  expected: %q\n  got: %q", expected, content)
   369→		}
   370→		return nil
   371→	}
   372→}
   373→
   374→// CheckRemoteFileMode returns a TestCheckFunc that verifies remote file permissions.
   375→func CheckRemoteFileMode(container *SSHTestContainer, path, expected string) resource.TestCheckFunc {
   376→	return func(s *terraform.State) error {
   377→		mode, err := container.GetFileModeNoHelper(path)
   378→		if err != nil {
   379→			return fmt.Errorf("failed to get file mode: %w", err)
   380→		}
   381→		mode = strings.TrimSpace(mode)
   382→		if mode != expected {
   383→			return fmt.Errorf("remote file mode mismatch:\n  expected: %s\n  got: %s", expected, mode)
   384→		}
   385→		return nil
   386→	}
   387→}
   388→
   389→// CheckRemoteFileSizeEquals returns a TestCheckFunc that verifies remote file size.
   390→func CheckRemoteFileSizeEquals(container *SSHTestContainer, path string, expectedSize int64) resource.TestCheckFunc {
   391→	return func(s *terraform.State) error {
   392→		output, err := container.runCommand(fmt.Sprintf("stat -c%%s %q", path))
   393→		if err != nil {
   394→			return fmt.Errorf("failed to get file size: %w", err)
   395→		}
   396→		var actualSize int64
   397→		if _, err := fmt.Sscanf(strings.TrimSpace(output), "%d", &actualSize); err != nil {
   398→			return fmt.Errorf("failed to parse file size: %w", err)
   399→		}
   400→		if actualSize != expectedSize {
   401→			return fmt.Errorf("remote file size mismatch:\n  expected: %d\n  got: %d", expectedSize, actualSize)
   402→		}
   403→		return nil
   404→	}
   405→}
   406→
   407→// CaptureHash returns a TestCheckFunc that captures the source_hash attribute.
   408→func CaptureHash(resourceName string, hashPtr *string) resource.TestCheckFunc {
   409→	return func(s *terraform.State) error {
   410→		rs, ok := s.RootModule().Resources[resourceName]
   411→		if !ok {
   412→			return fmt.Errorf("resource not found: %s", resourceName)
   413→		}
   414→		*hashPtr = rs.Primary.Attributes["source_hash"]
   415→		return nil
   416→	}
   417→}
   418→
   419→// CheckHashChanged returns a TestCheckFunc that verifies the hash changed.
   420→func CheckHashChanged(resourceName string, oldHashPtr *string) resource.TestCheckFunc {
   421→	return func(s *terraform.State) error {
   422→		rs, ok := s.RootModule().Resources[resourceName]
   423→		if !ok {
   424→			return fmt.Errorf("resource not found: %s", resourceName)
   425→		}
   426→		newHash := rs.Primary.Attributes["source_hash"]
   427→		if newHash == *oldHashPtr {
   428→			return fmt.Errorf("hash did not change: %s", newHash)
   429→		}
   430→		return nil
   431→	}
   432→}
