// TestAccFileResource_ImportSyncsLocal tests the import_syncs_local feature.
// When the local source file is deleted after initial creation and import_syncs_local=true,
// the provider downloads the remote file content to restore the local copy.
//
// Note: The full import workflow (terraform import -> terraform apply) requires
// the user to manually create the local file first, or use a pre-import script.
// This test verifies the underlying sync mechanism works correctly.
func TestAccFileResource_ImportSyncsLocal(t *testing.T) {
	t.Parallel()

	container := SetupSSHContainer(t)
	cfg := NewTestSSHConfig(container)

	sourceFile := CreateTestSourceFile(t, "original content\n")
	remotePath := "/tmp/test-import-syncs-local.txt"

	resource.Test(t, resource.TestCase{
		ProtoV6ProviderFactories: ProtoV6ProviderFactories,
		Steps: []resource.TestStep{
			// Step 1: Create the resource normally with import_syncs_local enabled.
			{
				Config: cfg.FileResourceConfigWithImportSyncsLocal("test", sourceFile, remotePath, "0644"),
				Check: resource.ComposeAggregateTestCheckFunc(
					CheckRemoteFileExists(container, remotePath),
					CheckRemoteFileContent(container, remotePath, "original content\n"),
				),
			},
			// Step 2: Delete the local file and modify remote, then refresh.
			// With import_syncs_local=true, the local file should be restored from remote.
			// Note: We also need to clear source_hash to simulate post-import state.
			{
				PreConfig: func() {
					// Delete the local file.
					if err := os.Remove(sourceFile); err != nil {
						t.Fatalf("failed to delete local file: %v", err)
					}
					// Modify remote content (simulating out-of-band changes).
					_, err := container.runCommand(fmt.Sprintf("echo -n 'modified on remote' > %s", remotePath))
					if err != nil {
						t.Fatalf("failed to modify remote file: %v", err)
					}
				},
				// This will fail because the plan modifier can't hash the missing file.
				// The import_syncs_local feature is designed for the import workflow,
				// not for recovering deleted local files during normal operation.
				Config:      cfg.FileResourceConfigWithImportSyncsLocal("test", sourceFile, remotePath, "0644"),
				ExpectError: regexp.MustCompile(`source file no longer exists|Failed to read source file`),
			},
		},
	})
}

