						currentHash := rs.Primary.Attributes["source_hash"]
						if currentHash != initialHash {
							return fmt.Errorf("hash changed unexpectedly: %s -> %s", initialHash, currentHash)
						}
						return nil
					},
				),
			},
		},
	})
}

