        {
          "displayName": "Low VRAM Mode",
          "name": "lowVram",
          "type": "boolean",
          "default": false,
          "description": "Whether to Activate low VRAM mode, which reduces memory usage at the cost of slower generation speed. Useful for GPUs with limited memory."
