{
  "name": "Discord AI Assistant",
  "nodes": [
    {
      "parameters": {
        "httpMethod": "POST",
        "path": "discord-updates",
        "responseMode": "responseNode",
        "options": {}
      },
      "id": "webhook-trigger",
      "name": "Discord Webhook",
      "type": "n8n-nodes-base.webhook",
      "position": [180, 300],
      "typeVersion": 2,
      "webhookId": "discord-updates"
    },
    {
      "parameters": {
        "assignments": {
          "assignments": [
            {
              "id": "user_message",
              "name": "user_message",
              "type": "string",
              "value": "={{ $json.body.message }}"
            },
            {
              "id": "user_id",
              "name": "user_id",
              "type": "string",
              "value": "={{ $json.body.userId }}"
            },
            {
              "id": "user_name",
              "name": "user_name",
              "type": "string",
              "value": "={{ $json.body.userName }}"
            },
            {
              "id": "channel_id",
              "name": "channel_id",
              "type": "string",
              "value": "={{ $json.body.channelId }}"
            },
            {
              "id": "is_dm",
              "name": "is_dm",
              "type": "boolean",
              "value": "={{ $json.body.isDM }}"
            }
          ]
        },
        "options": {}
      },
      "id": "extract-message",
      "name": "Extract Message",
      "type": "n8n-nodes-base.set",
      "position": [380, 300],
      "typeVersion": 3.4
    },
    {
      "parameters": {
        "promptType": "define",
        "text": "={{ $json.user_message }}",
        "hasOutputParser": false,
        "options": {
          "systemMessage": "You are a helpful Docker Update Assistant for a homelab infrastructure. You help users manage Docker container updates across their LXC containers.\n\nYou have access to tools that can:\n1. Check for available Docker container updates across the homelab\n2. Fetch changelogs for specific Docker images\n3. Get the current status of containers\n\nWhen users ask about updates:\n- Use the check_updates tool to see what updates are available\n- Provide a clear summary of which containers have updates\n- When asked about a specific container, fetch and summarize its changelog\n\nBe concise but helpful. Format your responses for Discord (use markdown sparingly, avoid code blocks for simple text).\n\nUser info:\n- Name: {{ $json.user_name }}\n- User ID: {{ $json.user_id }}"
        }
      },
      "id": "ai-agent",
      "name": "AI Agent",
      "type": "@n8n/n8n-nodes-langchain.agent",
      "position": [600, 300],
      "typeVersion": 1.7
    },
    {
      "parameters": {
        "model": "llama3.2:latest",
        "options": {
          "temperature": 0.7,
          "numCtx": 4096
        }
      },
      "id": "ollama-model",
      "name": "Ollama Chat Model",
      "type": "@n8n/n8n-nodes-langchain.lmChatOllama",
      "position": [480, 520],
      "typeVersion": 1
    },
    {
      "parameters": {
        "sessionIdType": "customKey",
        "sessionKey": "={{ $('Extract Message').item.json.user_id }}"
      },
      "id": "memory",
      "name": "Window Buffer Memory",
      "type": "@n8n/n8n-nodes-langchain.memoryBufferWindow",
      "position": [620, 520],
      "typeVersion": 1.3
    },
    {
      "parameters": {
        "name": "check_updates",
        "description": "Check for available Docker container updates across all LXC containers in the homelab. Returns a list of containers that have updates available, including current version, latest version, and container name.",
        "workflowId": "={{ $workflow.id }}",
        "responsePropertyName": "updates",
        "fields": {
          "values": []
        }
      },
      "id": "tool-check-updates",
      "name": "Check Updates Tool",
      "type": "@n8n/n8n-nodes-langchain.toolWorkflow",
      "position": [760, 520],
      "typeVersion": 2.1
    },
    {
      "parameters": {
        "respondWith": "json",
        "responseBody": "={{ JSON.stringify({ answer: $json.output }) }}",
        "options": {}
      },
      "id": "respond-webhook",
      "name": "Respond to Discord",
      "type": "n8n-nodes-base.respondToWebhook",
      "position": [820, 300],
      "typeVersion": 1.1
    },
    {
      "parameters": {
        "content": "## Discord AI Assistant\n\nReceives messages from Discord bot and responds using AI.\n\n**Webhook:** `/webhook/discord-updates`\n\n**Features:**\n- Conversational AI using local Ollama/llama.cpp\n- Per-user conversation memory\n- Tools for checking Docker updates\n\n**Requires:**\n- Ollama API credentials pointing to OpenWebUI\n- Docker Update Checker workflow for updates tool",
        "height": 280,
        "width": 340
      },
      "id": "sticky-header",
      "name": "Info",
      "type": "n8n-nodes-base.stickyNote",
      "position": [160, -20],
      "typeVersion": 1
    },
    {
      "parameters": {
        "content": "## AI Agent\n\nProcesses user messages with:\n- System prompt for Docker assistant role\n- Connected tools for checking updates\n- Memory for conversation context",
        "height": 160,
        "width": 260
      },
      "id": "sticky-agent",
      "name": "Agent Info",
      "type": "n8n-nodes-base.stickyNote",
      "position": [560, 120],
      "typeVersion": 1
    }
  ],
  "connections": {
    "Discord Webhook": {
      "main": [
        [
          {
            "node": "Extract Message",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Extract Message": {
      "main": [
        [
          {
            "node": "AI Agent",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "AI Agent": {
      "main": [
        [
          {
            "node": "Respond to Discord",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Ollama Chat Model": {
      "ai_languageModel": [
        [
          {
            "node": "AI Agent",
            "type": "ai_languageModel",
            "index": 0
          }
        ]
      ]
    },
    "Window Buffer Memory": {
      "ai_memory": [
        [
          {
            "node": "AI Agent",
            "type": "ai_memory",
            "index": 0
          }
        ]
      ]
    },
    "Check Updates Tool": {
      "ai_tool": [
        [
          {
            "node": "AI Agent",
            "type": "ai_tool",
            "index": 0
          }
        ]
      ]
    }
  },
  "settings": {
    "executionOrder": "v1",
    "timezone": "America/Los_Angeles"
  },
  "staticData": null,
  "meta": {
    "templateCredsSetupCompleted": false
  },
  "pinData": {},
  "active": false
}

