        "options": {}
      },
      "id": "webhook-trigger",
      "name": "Discord Webhook",
      "type": "n8n-nodes-base.webhook",
      "position": [180, 300],
      "typeVersion": 2,
      "webhookId": "discord-updates"
    },
    {
      "parameters": {
        "assignments": {
          "assignments": [
            {
              "id": "user_message",
              "name": "user_message",
              "type": "string",
              "value": "={{ $json.body.message }}"
            },
            {
              "id": "user_id",
