            {
              "id": "channel_id",
              "name": "channel_id",
              "type": "string",
              "value": "={{ $json.body.channelId }}"
            },
            {
              "id": "is_dm",
              "name": "is_dm",
              "type": "boolean",
              "value": "={{ $json.body.isDM }}"
            }
          ]
        },
        "options": {}
      },
      "id": "extract-message",
      "name": "Extract Message",
      "type": "n8n-nodes-base.set",
      "position": [380, 300],
      "typeVersion": 3.4
    },
    {
      "parameters": {
        "promptType": "define",
        "text": "={{ $json.user_message }}",
        "hasOutputParser": false,
