{
  "name": "Discord AI Assistant",
  "nodes": [
    {
      "parameters": {
        "httpMethod": "POST",
        "path": "discord-updates",
        "responseMode": "responseNode",
        "options": {
          "responseData": "allEntries"
        }
      },
      "id": "webhook-trigger",
      "name": "Discord Webhook",
      "type": "n8n-nodes-base.webhook",
      "position": [180, 300],
      "typeVersion": 2.1,
      "webhookId": "discord-updates",
      "onError": "continueRegularOutput"
    },
    {
      "parameters": {
        "assignments": {
          "assignments": [
            {
              "id": "user_message",
              "name": "user_message",
              "type": "string",
              "value": "={{ $json.body.message }}"
            },
            {
              "id": "user_id",
              "name": "user_id",
              "type": "string",
              "value": "={{ $json.body.userId }}"
            },
            {
              "id": "user_name",
              "name": "user_name",
              "type": "string",
              "value": "={{ $json.body.userName }}"
            },
            {
              "id": "channel_id",
              "name": "channel_id",
              "type": "string",
              "value": "={{ $json.body.channelId }}"
            },
            {
              "id": "is_dm",
              "name": "is_dm",
              "type": "boolean",
              "value": "={{ $json.body.isDM }}"
            }
          ]
        },
        "options": {}
      },
      "id": "extract-message",
      "name": "Extract Message",
      "type": "n8n-nodes-base.set",
      "position": [380, 300],
      "typeVersion": 3.4
    },
    {
      "parameters": {
        "promptType": "define",
        "text": "={{ $json.user_message }}",
        "hasOutputParser": false,
        "options": {
          "systemMessage": "You are a helpful Docker Update Assistant for a homelab infrastructure. You help users manage Docker container updates across their LXC containers.\n\nYou have access to tools that can:\n1. Check for available Docker container updates across the homelab\n2. Fetch changelogs/release notes for specific Docker images from GitHub\n\nWhen users ask about updates:\n- Use the check_updates tool to see what updates are available\n- Provide a clear summary of which containers have updates\n- When asked about a specific container's changelog, use the fetch_changelog tool\n\nBe concise but helpful. Format your responses for Discord (use markdown sparingly, keep responses under 1800 chars if possible).\n\nCommon GitHub repositories for homelab containers:\n- immich-app/immich (Immich photo management)\n- grafana/grafana (Grafana dashboards)\n- n8nio/n8n (n8n workflow automation)\n- jellyfin/jellyfin (Jellyfin media server)\n- goauthentik/authentik (Authentik identity provider)\n- traefik/traefik (Traefik reverse proxy)\n\nUser info:\n- Name: {{ $json.user_name }}\n- User ID: {{ $json.user_id }}"
        }
      },
      "id": "ai-agent",
      "name": "AI Agent",
      "type": "@n8n/n8n-nodes-langchain.agent",
      "position": [600, 300],
      "typeVersion": 3.1
    },
    {
      "parameters": {
        "model": {
          "__rl": true,
          "mode": "id",
          "value": "llama-3.2-3b-instruct"
        },
        "options": {
          "baseURL": "http://10.100.5.101:8080/v1",
          "temperature": 0.7,
          "maxTokens": 2048
        }
      },
      "id": "openai-model",
      "name": "OpenAI Chat Model",
      "type": "@n8n/n8n-nodes-langchain.lmChatOpenAi",
      "position": [480, 520],
      "typeVersion": 1.3
    },
    {
      "parameters": {
        "sessionIdType": "customKey",
        "sessionKey": "={{ $('Extract Message').item.json.user_id }}"
      },
      "id": "memory",
      "name": "Window Buffer Memory",
      "type": "@n8n/n8n-nodes-langchain.memoryBufferWindow",
      "position": [620, 520],
      "typeVersion": 1.3
    },
    {
      "parameters": {
        "toolDescription": "Check for available Docker container updates across all LXC containers in the homelab. Returns a summary of containers that have updates available. No parameters needed.",
        "method": "GET",
        "url": "http://localhost:5678/webhook/docker-update-checker",
        "authentication": "none",
        "optimizeResponse": true
      },
      "id": "tool-check-updates",
      "name": "Check Updates",
      "type": "@n8n/n8n-nodes-langchain.toolHttpRequest",
      "position": [760, 520],
      "typeVersion": 1.1
    },
    {
      "parameters": {
        "toolDescription": "Fetch changelog/release notes for a Docker image from GitHub. Use this when users want to know what changed in a specific container update. Provide the GitHub repository in owner/repo format (e.g., 'immich-app/immich', 'grafana/grafana', 'n8nio/n8n'). Returns the latest release notes.",
        "method": "GET",
        "url": "=https://api.github.com/repos/{repository}/releases/latest",
        "authentication": "none",
        "sendHeaders": true,
        "headerParameters": {
          "parameters": [
            {
              "name": "Accept",
              "value": "application/vnd.github.v3+json"
            },
            {
              "name": "User-Agent",
              "value": "n8n-discord-bot"
            }
          ]
        },
        "placeholderDefinitions": {
          "values": [
            {
              "name": "repository",
              "description": "The GitHub repository in owner/repo format (e.g., 'immich-app/immich', 'grafana/grafana')"
            }
          ]
        },
        "optimizeResponse": true
      },
      "id": "tool-fetch-changelog",
      "name": "Fetch Changelog",
      "type": "@n8n/n8n-nodes-langchain.toolHttpRequest",
      "position": [900, 520],
      "typeVersion": 1.1
    },
    {
      "parameters": {
        "respondWith": "json",
        "responseBody": "={{ JSON.stringify({ answer: $json.output }) }}",
        "options": {}
      },
      "id": "respond-webhook",
      "name": "Respond to Discord",
      "type": "n8n-nodes-base.respondToWebhook",
      "position": [820, 300],
      "typeVersion": 1.5
    },
    {
      "parameters": {
        "respondWith": "json",
        "responseBody": "={{ JSON.stringify({ answer: 'Sorry, something went wrong processing your request. Please try again.' }) }}",
        "options": {}
      },
      "id": "error-response",
      "name": "Error Response",
      "type": "n8n-nodes-base.respondToWebhook",
      "position": [820, 500],
      "typeVersion": 1.5
    },
    {
      "parameters": {
        "content": "## Discord AI Assistant\n\nReceives messages from Discord bot and responds using AI.\n\n**Webhook:** `/webhook/discord-updates`\n\n**Features:**\n- Conversational AI using local llama.cpp (OpenAI-compatible API)\n- Per-user conversation memory\n- Tool: Check Docker updates via existing workflow\n- Tool: Fetch changelogs from GitHub releases\n\n**Setup:**\n1. Configure OpenAI credentials with:\n   - API Key: `not-needed` (any value works)\n   - Base URL override in node: `http://10.100.5.101:8080/v1`\n2. Ensure Docker Update Checker workflow is active\n3. Activate this workflow",
        "height": 340,
        "width": 380
      },
      "id": "sticky-header",
      "name": "Info",
      "type": "n8n-nodes-base.stickyNote",
      "position": [160, -80],
      "typeVersion": 1
    },
    {
      "parameters": {
        "content": "## Tools\n\n**Check Updates:** Calls Docker Update Checker webhook\n**Fetch Changelog:** Gets GitHub release notes for containers",
        "height": 120,
        "width": 280
      },
      "id": "sticky-tools",
      "name": "Tools Info",
      "type": "n8n-nodes-base.stickyNote",
      "position": [740, 400],
      "typeVersion": 1
    }
  ],
  "connections": {
    "Discord Webhook": {
      "main": [
        [
          {
            "node": "Extract Message",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Extract Message": {
      "main": [
        [
          {
            "node": "AI Agent",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "AI Agent": {
      "main": [
        [
          {
            "node": "Respond to Discord",
            "type": "main",
            "index": 0
          }
        ],
        [
          {
            "node": "Error Response",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "OpenAI Chat Model": {
      "ai_languageModel": [
        [
          {
            "node": "AI Agent",
            "type": "ai_languageModel",
            "index": 0
          }
        ]
      ]
    },
    "Window Buffer Memory": {
      "ai_memory": [
        [
          {
            "node": "AI Agent",
            "type": "ai_memory",
            "index": 0
          }
        ]
      ]
    },
    "Check Updates": {
      "ai_tool": [
        [
          {
            "node": "AI Agent",
            "type": "ai_tool",
            "index": 0
          }
        ]
      ]
    },
    "Fetch Changelog": {
      "ai_tool": [
        [
          {
            "node": "AI Agent",
            "type": "ai_tool",
            "index": 0
          }
        ]
      ]
    }
  },
  "settings": {
    "executionOrder": "v1",
    "timezone": "America/Los_Angeles"
  },
  "staticData": null,
  "meta": {
    "templateCredsSetupCompleted": false
  },
  "pinData": {},
  "active": false
}

