/**
 * Discord Bot for n8n Integration
 *
 * This bot listens for mentions and DMs, forwards them to an n8n webhook,
 * and replies with the response. Designed for conversational AI workflows.
 *
 * Environment variables:
 *   DISCORD_BOT_TOKEN  - Discord bot token
 *   N8N_WEBHOOK_URL    - n8n webhook URL to forward messages to
 *   ALLOWED_CHANNEL_ID - (optional) Restrict to specific channel
 *   ALLOWED_USER_IDS   - (optional) Comma-separated list of allowed user IDs
 */

const { Client, GatewayIntentBits, Partials } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
    GatewayIntentBits.DirectMessages,
  ],
  partials: [Partials.Channel, Partials.Message],
});

const DISCORD_BOT_TOKEN = process.env.DISCORD_BOT_TOKEN;
const N8N_WEBHOOK_URL = process.env.N8N_WEBHOOK_URL || 'http://n8n:5678/webhook/discord';
const ALLOWED_CHANNEL_ID = process.env.ALLOWED_CHANNEL_ID || null;
const ALLOWED_USER_IDS = process.env.ALLOWED_USER_IDS
  ? process.env.ALLOWED_USER_IDS.split(',').map(id => id.trim())
  : null;

if (!DISCORD_BOT_TOKEN) {
  console.error('Error: DISCORD_BOT_TOKEN environment variable is required');
  process.exit(1);
}

client.once('ready', () => {
  console.log(`Discord bot logged in as ${client.user.tag}`);
  console.log(`Webhook URL: ${N8N_WEBHOOK_URL}`);
  if (ALLOWED_CHANNEL_ID) {
    console.log(`Restricted to channel: ${ALLOWED_CHANNEL_ID}`);
  }
  if (ALLOWED_USER_IDS) {
    console.log(`Allowed users: ${ALLOWED_USER_IDS.join(', ')}`);
  }
});

client.on('messageCreate', async (message) => {
  // Ignore messages from bots
  if (message.author.bot) return;

  // Check if this is a DM or a mention
  const isDM = !message.guild;
  const isMentioned = message.mentions.has(client.user);

  // Only process DMs or mentions
  if (!isDM && !isMentioned) return;

  // Check channel restriction
  if (ALLOWED_CHANNEL_ID && message.channel.id !== ALLOWED_CHANNEL_ID && !isDM) {
    return;
  }

  // Check user restriction
  if (ALLOWED_USER_IDS && !ALLOWED_USER_IDS.includes(message.author.id)) {
    console.log(`Ignoring message from unauthorized user: ${message.author.tag} (${message.author.id})`);
    return;
  }

  // Extract the actual question (remove bot mention)
  let content = message.content;
  if (isMentioned) {
    content = content.replace(/<@!?\d+>/g, '').trim();
  }

  // Don't process empty messages
  if (!content) {
    await message.reply("Hi! How can I help you? Ask me about Docker container updates.");
    return;
  }

  console.log(`Processing message from ${message.author.tag}: ${content.substring(0, 100)}...`);

  // Show typing indicator
  const typingInterval = setInterval(() => {
    message.channel.sendTyping().catch(() => {});
  }, 5000);
  message.channel.sendTyping().catch(() => {});

  try {
    // Forward to n8n webhook
    const response = await fetch(N8N_WEBHOOK_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        message: content,
        userId: message.author.id,
        userName: message.author.tag,
        channelId: message.channel.id,
        channelName: message.channel.name || 'DM',
        guildId: message.guild?.id || null,
        guildName: message.guild?.name || null,
        messageId: message.id,
        isDM: isDM,
        timestamp: message.createdTimestamp,
      }),
    });

    clearInterval(typingInterval);

    if (!response.ok) {
      const errorText = await response.text();
      console.error(`n8n webhook error: ${response.status} - ${errorText}`);
      await message.reply("Sorry, I'm having trouble processing your request right now. Please try again later.");
      return;
    }

    const data = await response.json();
    const reply = data.answer || data.response || data.message || "I processed your request but have no response.";

    // Discord has a 2000 character limit - split if necessary
    if (reply.length <= 2000) {
      await message.reply(reply);
    } else {
      // Split into chunks at sentence boundaries
      const chunks = splitMessage(reply, 1900);
      for (const chunk of chunks) {
        await message.reply(chunk);
        // Small delay between messages
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
  } catch (error) {
    clearInterval(typingInterval);
    console.error('Error processing message:', error);
    await message.reply("Sorry, something went wrong. Please try again later.");
  }
});

/**
 * Split a long message into chunks at sentence/paragraph boundaries
 */
function splitMessage(text, maxLength) {
  const chunks = [];
  let remaining = text;

  while (remaining.length > 0) {
    if (remaining.length <= maxLength) {
      chunks.push(remaining);
      break;
    }

    // Find a good split point
    let splitPoint = remaining.lastIndexOf('\n\n', maxLength);
    if (splitPoint === -1 || splitPoint < maxLength / 2) {
      splitPoint = remaining.lastIndexOf('\n', maxLength);
    }
    if (splitPoint === -1 || splitPoint < maxLength / 2) {
      splitPoint = remaining.lastIndexOf('. ', maxLength);
      if (splitPoint !== -1) splitPoint += 1; // Include the period
    }
    if (splitPoint === -1 || splitPoint < maxLength / 2) {
      splitPoint = remaining.lastIndexOf(' ', maxLength);
    }
    if (splitPoint === -1) {
      splitPoint = maxLength;
    }

    chunks.push(remaining.substring(0, splitPoint).trim());
    remaining = remaining.substring(splitPoint).trim();
  }

  return chunks;
}

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('Received SIGTERM, shutting down...');
  client.destroy();
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('Received SIGINT, shutting down...');
  client.destroy();
  process.exit(0);
});

// Login
client.login(DISCORD_BOT_TOKEN);

