     1→/**
     2→ * Discord Bot for n8n Integration
     3→ *
     4→ * This bot listens for mentions and DMs, forwards them to an n8n webhook,
     5→ * and replies with the response. Designed for conversational AI workflows.
     6→ *
     7→ * Environment variables:
     8→ *   DISCORD_BOT_TOKEN  - Discord bot token
     9→ *   N8N_WEBHOOK_URL    - n8n webhook URL to forward messages to
    10→ *   ALLOWED_CHANNEL_ID - (optional) Restrict to specific channel
    11→ *   ALLOWED_USER_IDS   - (optional) Comma-separated list of allowed user IDs
    12→ */
    13→
    14→const { Client, GatewayIntentBits, Partials } = require('discord.js');
    15→
    16→const client = new Client({
    17→  intents: [
    18→    GatewayIntentBits.Guilds,
    19→    GatewayIntentBits.GuildMessages,
    20→    GatewayIntentBits.MessageContent,
    21→    GatewayIntentBits.DirectMessages,
    22→  ],
    23→  partials: [Partials.Channel, Partials.Message],
    24→});
    25→
    26→const DISCORD_BOT_TOKEN = process.env.DISCORD_BOT_TOKEN;
    27→const N8N_WEBHOOK_URL = process.env.N8N_WEBHOOK_URL || 'http://n8n:5678/webhook/discord';
    28→const ALLOWED_CHANNEL_ID = process.env.ALLOWED_CHANNEL_ID || null;
    29→const ALLOWED_USER_IDS = process.env.ALLOWED_USER_IDS
    30→  ? process.env.ALLOWED_USER_IDS.split(',').map(id => id.trim())
    31→  : null;
    32→
    33→if (!DISCORD_BOT_TOKEN) {
    34→  console.error('Error: DISCORD_BOT_TOKEN environment variable is required');
    35→  process.exit(1);
    36→}
    37→
    38→client.once('ready', () => {
    39→  console.log(`Discord bot logged in as ${client.user.tag}`);
    40→  console.log(`Webhook URL: ${N8N_WEBHOOK_URL}`);
    41→  if (ALLOWED_CHANNEL_ID) {
    42→    console.log(`Restricted to channel: ${ALLOWED_CHANNEL_ID}`);
    43→  }
    44→  if (ALLOWED_USER_IDS) {
    45→    console.log(`Allowed users: ${ALLOWED_USER_IDS.join(', ')}`);
    46→  }
    47→});
    48→
    49→client.on('messageCreate', async (message) => {
    50→  // Ignore messages from bots
    51→  if (message.author.bot) return;
    52→
    53→  // Check if this is a DM or a mention
    54→  const isDM = !message.guild;
    55→  const isMentioned = message.mentions.has(client.user);
    56→
    57→  // Only process DMs or mentions
    58→  if (!isDM && !isMentioned) return;
    59→
    60→  // Check channel restriction
    61→  if (ALLOWED_CHANNEL_ID && message.channel.id !== ALLOWED_CHANNEL_ID && !isDM) {
    62→    return;
    63→  }
    64→
    65→  // Check user restriction
    66→  if (ALLOWED_USER_IDS && !ALLOWED_USER_IDS.includes(message.author.id)) {
    67→    console.log(`Ignoring message from unauthorized user: ${message.author.tag} (${message.author.id})`);
    68→    return;
    69→  }
    70→
    71→  // Extract the actual question (remove bot mention)
    72→  let content = message.content;
    73→  if (isMentioned) {
    74→    content = content.replace(/<@!?\d+>/g, '').trim();
    75→  }
    76→
    77→  // Don't process empty messages
    78→  if (!content) {
    79→    await message.reply("Hi! How can I help you? Ask me about Docker container updates.");
    80→    return;
    81→  }
    82→
    83→  console.log(`Processing message from ${message.author.tag}: ${content.substring(0, 100)}...`);
    84→
    85→  // Show typing indicator
    86→  const typingInterval = setInterval(() => {
    87→    message.channel.sendTyping().catch(() => {});
    88→  }, 5000);
    89→  message.channel.sendTyping().catch(() => {});
    90→
    91→  try {
    92→    // Forward to n8n webhook
    93→    const response = await fetch(N8N_WEBHOOK_URL, {
    94→      method: 'POST',
    95→      headers: {
    96→        'Content-Type': 'application/json',
    97→      },
    98→      body: JSON.stringify({
    99→        message: content,
   100→        userId: message.author.id,
