      "type": "n8n-nodes-base.manualTrigger",
      "position": [
        208,
        304
      ],
      "typeVersion": 1
    },
    {
      "parameters": {
        "assignments": {
          "assignments": [
            {
              "id": "lxcs",
              "name": "lxcs",
              "type": "array",
              "value": "={{ [\n  { \"id\": \"101\", \"name\": \"network-services\" },\n  { \"id\": \"104\", \"name\": \"container-mgmt\" },\n  { \"id\": \"200\", \"name\": \"traefik\" },\n  { \"id\": \"201\", \"name\": \"dashboards\" },\n  { \"id\": \"203\", \"name\": \"authentik\" },\n  { \"id\": \"303\", \"name\": \"immich-importer\" },\n  { \"id\": \"304\", \"name\": \"immich\" },\n  { \"id\": \"401\", \"name\": \"jellyfin\" },\n  { \"id\": \"402\", \"name\": \"media-management\" },\n  { \"id\": \"500\", \"name\": \"monitoring\" },\n  { \"id\": \"501\", \"name\": \"openwebui\" },\n  { \"id\": \"502\", \"name\": \"n8n\" },\n  { \"id\": \"503\", \"name\": \"obsidian-sync\" },\n  { \"id\": \"504\", \"name\": \"documents\" }\n] }}"
            },
            {
              "id": "ntfy_url",
              "name": "ntfy_url",
              "type": "string",
              "value": "http://10.100.5.100:8080/docker-updates?template=docker-updates"
            },
            {
              "id": "proxmox_host",
              "name": "proxmox_host",
              "type": "string",
              "value": "10.100.0.1"
            },
            {
              "id": "include_prerelease",
              "name": "include_prerelease",
              "type": "boolean",
              "value": false
            }
          ]
        },
        "options": {}
      },
      "id": "config",
      "name": "Configuration",
      "type": "n8n-nodes-base.set",
      "position": [
        400,
        400
      ],
      "typeVersion": 3.4
    },
    {
      "parameters": {
        "fieldToSplitOut": "lxcs",
        "options": {}
      },
      "id": "split-lxcs",
      "name": "Split LXCs",
      "type": "n8n-nodes-base.splitOut",
      "position": [
        608,
        400
      ],
      "typeVersion": 1
    },
    {
      "parameters": {
        "command": "=pct exec {{ $json.id }} -- docker ps --format json"
      },
      "id": "get-containers",
      "name": "Get Running Containers",
      "type": "n8n-nodes-base.ssh",
      "position": [
        800,
        400
      ],
      "typeVersion": 1,
      "credentials": {
        "sshPassword": {
          "id": "yzSbZ0PMyfDbQ1fa",
          "name": "SSH Password account"
        }
      },
      "continueOnFail": true
    },
    {
      "parameters": {
        "jsCode": "const allContainers = [];\nconst seenImages = new Set();\nconst lxcItems = $('Split LXCs').all();\nconst sshItems = $input.all();\n\nfunction parseImage(image) {\n  let registry = 'docker.io', repository = image, tag = 'latest';\n  const tagMatch = repository.match(/^(.+):([^:]+)$/);\n  if (tagMatch) { repository = tagMatch[1]; tag = tagMatch[2]; }\n  if (repository.includes('/')) {\n    const firstPart = repository.split('/')[0];\n    if (firstPart.includes('.') || firstPart.includes(':')) {\n      registry = firstPart;\n      repository = repository.substring(firstPart.length + 1);\n    }\n  }\n  if (!repository.includes('/') && registry === 'docker.io') repository = 'library/' + repository;\n  return { registry, repository, current_tag: tag };\n}\n\nfor (let i = 0; i < sshItems.length; i++) {\n  const stdout = sshItems[i].json.stdout || '';\n  const lxcId = lxcItems[i]?.json?.id || 'unknown';\n  const lxcName = lxcItems[i]?.json?.name || 'unknown';\n  \n  for (const line of stdout.split('\\n')) {\n    if (!line.trim() || line === '{}') continue;\n    try {\n      const container = JSON.parse(line);\n      const name = container.Names || '', image = container.Image || '';\n      if (name && image && !seenImages.has(image)) {\n        seenImages.add(image);\n        allContainers.push({ json: { lxcId, lxcName, containerName: name, image, skip: false, ...parseImage(image) } });\n      }\n    } catch (e) {}\n  }\n}\n\nreturn allContainers.length ? allContainers : [{ json: { skip: true, skip_reason: 'No containers found' } }];"
      },
      "id": "parse-containers",
      "name": "Parse Container Info",
      "type": "n8n-nodes-base.code",
      "position": [
        1008,
        400
      ],
      "typeVersion": 2
    },
    {
      "parameters": {
        "jsCode": "const results = [];\nfor (const item of $input.all()) {\n  const c = item.json;\n  if (c.skip) { results.push({ json: c }); continue; }\n  \n  const { registry, repository: repo, current_tag: tag } = c;\n  if (!tag || tag.startsWith('sha256:')) { results.push({ json: { ...c, skip: true } }); continue; }\n  \n  let apiUrl = '', releaseUrl = '', registryType = '';\n  if (registry === 'docker.io' || registry === 'docker.n8n.io') {\n    registryType = 'dockerhub';\n    apiUrl = `https://hub.docker.com/v2/repositories/${repo}/tags?page_size=100`;\n    releaseUrl = `https://hub.docker.com/r/${repo.replace('library/', '')}/tags`;\n  } else if (registry === 'ghcr.io') {\n    registryType = 'ghcr';\n    const [owner, ...parts] = repo.split('/');\n    apiUrl = `https://api.github.com/users/${owner}/packages/container/${parts.join('/')}/versions?per_page=50`;\n    releaseUrl = `https://github.com/${repo}/pkgs/container/${parts.join('/')}`;\n  } else if (registry === 'lscr.io') {\n    registryType = 'lscr';\n    const repoName = repo.replace('linuxserver/', '');\n    apiUrl = `https://api.github.com/repos/linuxserver/docker-${repoName}/releases?per_page=20`;\n    releaseUrl = `https://github.com/linuxserver/docker-${repoName}/releases`;\n  } else { results.push({ json: { ...c, skip: true } }); continue; }\n  \n  results.push({ json: { ...c, apiUrl, releaseUrl, registryType } });\n}\nreturn results;"
      },
