          "jsCode": "const fetch = require('node-fetch');\nconst container = $input.item.json;\nconst includePrerelease = $('Configuration').first().json.include_prerelease;\nconst { registryType, current_tag: currentTag, apiUrl } = container;\n\nlet response;\ntry {\n  response = await fetch(apiUrl, { headers: { 'Accept': 'application/json', 'User-Agent': 'n8n' }, timeout: 15000 });\n} catch (e) { return { ...container, error: true, error_message: e.message, update_available: false }; }\nif (!response.ok) return { ...container, error: true, error_message: `HTTP ${response.status}`, update_available: false };\n\nlet data;\ntry { data = await response.json(); } catch (e) { return { ...container, error: true, update_available: false }; }\n\nlet tags = [];\nif (registryType === 'dockerhub') tags = (data.results || []).map(t => t.name);\nelse if (registryType === 'ghcr') tags = (data || []).flatMap(v => v.metadata?.container?.tags || []);\nelse if (registryType === 'lscr') tags = (data || []).filter(r => !r.prerelease || includePrerelease).map(r => r.tag_name);\n\n// Pre-release patterns - matches alpha, beta, rc, dev, etc.\n// Also matches: 3.15.0a3, v0.108.0-b.80, etc.\nconst prereleasePattern = /[-.](alpha|beta|rc|dev|preview|canary|nightly|test|unstable|next|react)(\\d*)([.-]|$)|[-.][ab]\\.\\d+([.-]|$)|\\d+[ab]\\d+([.-]|$)/i;\n// Invalid tag patterns (non-version strings)\nconst invalidPattern = /^(latest|edge|develop|main|master|nightly|sha256|sha-|pr-|test)/i;\n// Platform-specific patterns to exclude\nconst platformPattern = /(arm64|amd64|x86_64|windowsservercore|ltsc\\d+|linux)/i;\n// Build ID pattern (date-based builds or pure numeric)\nconst buildIdPattern = /^(\\d{4,})$|[-.](\\d{8,}|\\d{6}-\\d{6})($|[-.])/;\n// LinuxServer.io build suffix pattern (e.g., 4.0.16.2944-ls300)\nconst lscrBuildPattern = /\\.\\d{4,}-ls\\d+$/i;\n// All Debian/distro suffixes (bookworm, bullseye, trixie, alpine, etc.)\nconst distroSuffixes = ['alpine', 'bookworm', 'bullseye', 'buster', 'stretch', 'trixie', 'slim', 'jammy', 'noble', 'focal'];\nconst distroPattern = new RegExp('[-.]('+distroSuffixes.join('|')+')', 'i');\n\n// Extract distro suffix for matching same-distro tags (just the distro name, not version)\nconst getDistroSuffix = v => {\n  const match = v.match(distroPattern);\n  return match ? match[1].toLowerCase() : '';\n};\nconst currentDistro = getDistroSuffix(currentTag);\n\n// Extract base version for comparison\n// Strip: leading v, distro suffix, and LinuxServer build suffix\nconst getBase = v => {\n  let base = v.replace(/^v/, '');\n  // Remove LinuxServer.io build suffix (e.g., .2944-ls300)\n  base = base.replace(/\\.\\d{4,}-ls\\d+$/i, '');\n  // Remove distro suffix and anything after it\n  base = base.replace(new RegExp('[-.]('+distroSuffixes.join('|')+').*$', 'i'), '');\n  return base;\n};\nconst currentBase = getBase(currentTag);\n\n// Filter to valid semver tags only\nconst validTags = tags.filter(t => {\n  if (!t || invalidPattern.test(t)) return false;\n  // Must look like a version number (at minimum X.Y format, not just a number)\n  if (!/^v?\\d+\\.\\d+/.test(t)) return false;\n  // Exclude pure numeric tags (build numbers like 1243)\n  if (/^\\d+$/.test(t)) return false;\n  // Exclude platform-specific tags\n  if (platformPattern.test(t)) return false;\n  // Exclude build ID tags\n  if (buildIdPattern.test(t)) return false;\n  // Exclude pre-releases unless opted in\n  if (!includePrerelease && prereleasePattern.test(t)) return false;\n  // Prefer same distro variant if current has one (match distro name, ignore version like alpine3.23)\n  if (currentDistro) {\n    const tagDistro = getDistroSuffix(t);\n    // If tag has a distro suffix, it must match current distro (ignoring version numbers)\n    if (tagDistro && tagDistro !== currentDistro) return false;\n    // If current has distro but tag doesn't, prefer tags with matching distro\n    // Skip this filter - allow both distro and non-distro tags to compete on version