const data = $input.item.json.body;
const updates = data.updates || [];
const title = data.title || 'Docker Updates';

if (!updates.length) {
  return { json: { message: 'No Docker updates available at this time.' } };
}

let msg = `🐳 **${title}**\n\n`;

for (const lxc of updates) {
  msg += `**[${lxc.lxcName}]**\n`;
  for (const c of lxc.containers) {
    msg += `• ${c.name}: \`${c.current}\` → \`${c.latest}\`\n`;
  }
  msg += '\n';
}

msg += '_Run updates with caution. Check changelogs before upgrading._';

return { json: { message: msg } };"

