// HTTP server for receiving messages from n8n
const server = http.createServer(async (req, res) => {
  // Health check
  if (req.method === 'GET' && req.url === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok', connected: client.isReady() }));
    return;
  }

  // Send message endpoint
  if (req.method === 'POST' && req.url === '/send') {
    let body = '';
    req.on('data', chunk => { body += chunk; });
    req.on('end', async () => {
      try {
        const { channelId, message } = JSON.parse(body);

        if (!channelId || !message) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'channelId and message are required' }));
          return;
        }

        const channel = await client.channels.fetch(channelId);
        if (!channel || !channel.isTextBased()) {
          res.writeHead(404, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Channel not found or not a text channel' }));
          return;
        }

        // Split long messages
        const chunks = splitMessage(message, 1900);
        for (const chunk of chunks) {
          await channel.send(chunk);
          if (chunks.length > 1) await new Promise(r => setTimeout(r, 500));
        }

        console.log(`Sent message to channel ${channelId}`);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true }));
      } catch (error) {
        console.error('Error sending message:', error);
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: error.message }));
      }
    });
    return;
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(HTTP_PORT, () => {
  console.log(`HTTP server listening on port ${HTTP_PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('Received SIGTERM, shutting down...');
  server.close();
  client.destroy();
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('Received SIGINT, shutting down...');
  server.close();
  client.destroy();
  process.exit(0);
});

// Login
client.login(DISCORD_BOT_TOKEN);

