+        "jsCode": "// Filter updates based on skipped list and format for Discord
const staticData = $getWorkflowStaticData('global');
const skipped = staticData.skippedUpdates || {};

const data = $input.item.json.body || $input.item.json;
const allUpdates = data.updates || [];
const title = data.title || 'Docker Updates';

// Filter out skipped containers
const filteredUpdates = allUpdates.map(lxc => ({
  lxcName: lxc.lxcName,
  containers: lxc.containers.filter(c => !skipped[c.name.toLowerCase()])
})).filter(lxc => lxc.containers.length > 0);

const totalFiltered = filteredUpdates.reduce((sum, lxc) => sum + lxc.containers.length, 0);
const totalSkipped = allUpdates.reduce((sum, lxc) => sum + lxc.containers.length, 0) - totalFiltered;

if (totalFiltered === 0) {
  if (totalSkipped > 0) {
    return { json: { message: `No new Docker updates (${totalSkipped} skipped). Use \`list skipped\` to see what's being ignored.`, skip: true } };
  }
  return { json: { message: 'No Docker updates available at this time.', skip: true } };
}

let msg = `🐳 **${totalFiltered} Docker Updates**\n\n`;

for (const lxc of filteredUpdates) {
  msg += `**[${lxc.lxcName}]**\n`;
  for (const c of lxc.containers) {
    msg += `• ${c.name}: \`${c.current}\` → \`${c.latest}\`\n`;
  }
  msg += '\n';
}

if (totalSkipped > 0) {
  msg += `_${totalSkipped} update(s) hidden. Say \"list skipped\" to see them._\n`;
}
msg += '_Reply with container name to skip, or ask for changelog._';

return { json: { message: msg, skip: false } };"

